INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'evictions', 'Eviction diversion - mediation plus back-rent money before a case is filed', 'An eviction filing hurts a renter even if the case is later dropped, because it lands on screening reports. Eviction diversion requires landlords to try mediation and rent assistance for a set number of days before they can file. Philadelphia''s program shows that the combination of an agreement and money for back rent works best.', 'eviction diversion - mediation plus back-rent money before a case is filed', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "community", "who": {"government": "Cities and counties can pass a pre-filing diversion rule like Philadelphia''s, run it through the court, and fund a standing back-rent fund for small arrears. States can use their housing trust funds for it. Congress put $46.6 billion into Emergency Rental Assistance during the pandemic; the Eviction Lab found the money mostly reached the neighborhoods with the most evictions, and programs that paid tenants directly moved money faster. A smaller permanent version could be built on that.", "means": "Philanthropists, banks and local foundations can capitalize a \"small arrears\" fund that pays off debts under a few thousand dollars, where the evaluation shows money matters most. Employers can offer emergency grants or zero-interest loans for rent. Large landlords and property managers can adopt diversion voluntarily, offering a payment plan and a referral before any filing.", "you": "If you''re behind on rent but no case has been filed, call 211 or search your city or county name plus \"rental assistance\" and apply now, since payments can take weeks. At the same time, ask your landlord in writing for a repayment plan; the CFPB''s renter pages have steps for starting that conversation. If your city has an eviction diversion program, ask to be enrolled."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/evictions/solutions/eviction-diversion-with-rent-help.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'eviction diversion - mediation plus back-rent money before a case is filed');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'evictions', 'A free lawyer in eviction court (right to counsel)', 'In New York City before its law, only 1% of tenants in eviction cases had a lawyer, while more than 90% of landlords did. "Right to counsel" laws guarantee eligible tenants a free lawyer. Five states, 17 cities and one county passed these laws between 2017 and 2024. Anyone facing eviction can look for free legal aid today, even where no such law exists yet.', 'a free lawyer in eviction court (right to counsel)', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "community", "who": {"government": "City councils and state legislatures can pass a right-to-counsel law, starting with the groups most at risk (families with children, older tenants), as Akron, Ohio did in its 2025 pilot. Courts can require eviction notices to say, in plain words, where to get a free lawyer. Congress can keep funding the Legal Services Corporation, whose grantees spend about 40% of their cases on housing.", "means": "Philanthropists and community foundations can fund a right-to-counsel pilot in one county court for three years and pay for an independent evaluation, so the local government sees the results before taking it over. Law firms can commit pro bono hours every week to the local housing court. Employers can give workers a free legal-help benefit that covers housing cases. Large landlords can agree to pause a filing while a tenant''s legal aid application is pending.", "you": "If you have an eviction notice or court papers, go to LawHelp.org, pick your state and find a free legal aid group, or use the Legal Services Corporation''s \"Get legal help\" locator by entering your address. Call them the same day and say when your court date is. Then go to court: the CFPB warns that too many renters give up before their hearing, and responding to the case is how you raise defenses or get more time."}, "sources": 6, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/evictions/solutions/right-to-counsel-free-eviction-lawyer.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'a free lawyer in eviction court (right to counsel)');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'evictions', 'Seal eviction records and fix tenant screening reports', 'A single eviction filing can block someone from renting for years, even if they won the case, because screening companies copy court records into reports landlords rely on. States can seal eviction records, as California and Colorado do from the start of a case. Renters can already get a free copy of a screening report that cost them an apartment and dispute errors.', 'seal eviction records and fix tenant screening reports', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "state", "who": {"government": "State legislatures can pass automatic sealing at filing, with the record opened only if the landlord wins a judgment, and automatic sealing of dismissed, settled and tenant-won cases. State court systems can make case files unavailable to non-parties from the day of filing by court rule. Exceptions can allow verified researchers to use anonymized data, as D.C. law does. Federal agencies (CFPB and FTC) can keep enforcing accuracy rules for screening companies.", "means": "Large landlords and property managers can adopt written policies not to reject applicants for filings that were dismissed or won, or that are older than a few years, and to use current income and payment history instead. Legal tech funders and philanthropists can pay for free \"record clinics\" and simple online tools that file sealing petitions in every state where they''re allowed. Screening companies can verify identity with full date of birth before reporting a case.", "you": "If a landlord turned you down because of a screening report, ask for the company''s name and request your free copy (within 60 days). Check it for dismissed cases shown without the outcome, duplicates, cases that aren''t yours, or anything older than seven years, and dispute each error in writing with the screening company, using the CFPB''s \"Review your rental background check\" guide. Then ask a free legal aid group (find one at LawHelp.org) whether your state lets you petition to seal the case."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/evictions/solutions/seal-eviction-records-fix-screening.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'seal eviction records and fix tenant screening reports');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'evictions', 'A stay-put fund for renters when a building is sold or taxes jump', 'Good tenants lose homes when an owner sells or when property taxes rise faster than the rent can cover. A local "stay-put fund", backed by public, philanthropic and investor money, would get first notice when a small rental is sold and could buy it at market price to keep current tenants housed at stable rents. For owners who want to keep the building, it would offer a tax deal: property-tax relief in exchange for capped rent increases.', 'a stay-put fund for renters when a building is sold or taxes jump', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "community", "who": {"government": "City councils or county boards pass the first-offer notice rule and authorize the tax abatement. The local housing agency hosts the fund, as D.C.''s Department of Housing and Community Development does for its tenant purchase program. States can let local assessors offer the abatement and seed the fund from housing trust funds.", "means": "Philanthropists and community foundations can put in first-loss capital so banks and impact investors will lend the rest at low rates. Large employers can invest in the fund where their workers rent, as a way to keep their workforce housed. Banks can lend to the fund as part of their community development lending. Wealthy individuals can give or lend through a local community development financial institution. Landlords who are retiring can offer their building to the fund first.", "you": "If your landlord says they are selling or raising rent because of taxes, ask in writing for the sale timeline and the new rent, and check with a free legal aid group (LawHelp.org) whether your city or state gives tenants notice or purchase rights. Contact your local housing agency or community land trust to ask whether they buy buildings, and talk to your neighbors: a tenant group has more options than a single household."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/evictions/solutions/stay-put-fund-for-small-rentals.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'a stay-put fund for renters when a building is sold or taxes jump');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'health-care-costs', 'Lost your job? You have 60 days to get new coverage', 'Losing job-based insurance opens a Special Enrollment Period. You can sign up for a Marketplace plan within 60 days of losing coverage, or in the 60 days before it ends, without waiting for open enrollment. Medicaid takes applications all year. Savings are based on your expected income for the year, not on whether you have a job, so a drop in income after a layoff can make you eligible for help you didn''t get while working.', 'lost your job? you have 60 days to get new coverage', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "States can send Marketplace and Medicaid information with every unemployment claim and every layoff notice, and let people apply for coverage on the same site. Medicaid work requirements for expansion adults begin January 1, 2027, in most states (some states started earlier, KFF). States can make sure people who recently lost a job know which exemptions and grace periods apply to them.", "means": "Employers planning layoffs can give every departing worker a one-page sheet with their coverage end date, the 60-day deadline, a COBRA price next to an estimated Marketplace price, and time on the clock to meet a free enrollment helper. Foundations can fund certified enrollment assisters at unemployment offices and job centers.", "you": "1. Find your exact coverage end date from HR or your plan, and put the date 60 days later on your calendar. 2. Go to HealthCare.gov (or your state''s Marketplace if it runs its own) and fill out an application with your expected income for the year. See what plans, savings or Medicaid you qualify for before you decide on COBRA. 3. If you need help, use the HealthCare.gov \"Find Local Help\" page to find a free assister near you. 4. Until coverage starts, use a community health center for care. You can find one at findahealthcenter.hrsa.gov."}, "sources": 8, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/health-care-costs/solutions/after-a-layoff-get-covered-in-60-days.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'lost your job? you have 60 days to get new coverage');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'health-care-costs', 'Check the cash price and use $35 insulin programs before you skip a prescription', 'In early 2026, 27% of adults said they hadn''t filled a prescription in the past year because of cost (KFF). For many common generics, the cash price at a low-markup pharmacy is lower than people expect. For insulin, every Medicare plan caps the cost at $35 a month, and Lilly sells its insulins for $35 a month to people with commercial insurance or no insurance through December 31, 2026. Checking these takes about 15 minutes.', 'check the cash price and use $35 insulin programs before you skip a prescription', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "Congress could extend a $35 monthly insulin cap to private insurance and to uninsured people, matching the Medicare rule. States can do the same for plans they regulate. Medicaid programs and state employee plans can test low-markup pharmacy pricing for common generics.", "means": "Drug makers can extend $35 insulin cards past their end dates, publish them in plain language and let pharmacists apply them automatically for cash patients. Employers that pay for their own health plans can add a low-markup mail pharmacy for generics and pass the savings to workers. Hospital systems can check the cash price of every discharge prescription before a patient leaves. Philanthropists can pay for pharmacists at free clinics and health centers who help patients sign up for assistance programs.", "you": "1. Write down each medicine, its strength and how many pills a month. 2. Look it up at costplusdrugs.com and at TrumpRx.gov. Call your usual pharmacy and ask for its cash price too. Choose the cheapest one. 3. If you use Lilly insulin and don''t have Medicare or Medicaid, download the $35 card at insulins.lilly.com before your next refill. For other brands, check the American Diabetes Association list at diabetes.org. 4. If you can''t afford even those prices, ask your doctor''s office or a community health center to help you apply for the maker''s patient assistance program. 5. Don''t cut pills or skip doses without asking your prescriber. Ask whether a cheaper generic or a different drug would work instead."}, "sources": 7, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/health-care-costs/solutions/cash-drug-prices-and-insulin-programs.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'check the cash price and use $35 insulin programs before you skip a prescription');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'health-care-costs', '"Community health centers and dental schools: care priced by your income"', 'Federally funded community health centers see patients with or without insurance, and what you pay depends on your income. Many also offer dental and mental health care. Dental schools run supervised student clinics that are usually cheaper than private offices. Both already exist in most of the country, and many people who skip care because of cost don''t know about them.', '"community health centers and dental schools: care priced by your income"', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "community", "who": {"government": "KFF reports that federal health center funding expires in December 2026 and that the regular annual amount hasn''t been set yet. Congress can fund health centers for several years at a time so they can hire staff and plan. States can add adult dental benefits to Medicaid and pay health center dental teams enough to keep them. Cities can help with space for school-based and mobile clinics.", "means": "Hospital systems can send uninsured patients leaving the emergency room to a nearby health center for follow-up care, and pay for a staffer who books the appointment before the patient goes home. Employers with hourly workers can partner with a local center for on-site or after-hours clinics. Philanthropists and foundations can pay for dental chairs, mobile dental vans and dental residents at centers. Dental schools'' donors can fund free-care days for uninsured patients.", "you": "1. Go to findahealthcenter.hrsa.gov (the federal health center finder that HealthCare.gov links to), type your address and pick the nearest center. 2. Call and ask: \"Do you have a sliding fee scale? What do I need to bring to show my income?\" Bring a recent pay stub, an unemployment letter or a tax return. 3. For dental work, search \"dental school clinic\" plus your state, or call 2-1-1 and ask about free or reduced-cost dental care. 4. Ask the center whether it has an on-site or partner pharmacy with discounted prices."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/health-care-costs/solutions/community-health-centers-and-dental-schools.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = '"community health centers and dental schools: care priced by your income"');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'health-care-costs', '"Layoff health bridge: employers pay three months of coverage and a sign-up helper"', 'When a company lays people off, it would pay for each worker''s health coverage for three months, either by paying COBRA premiums or by giving the same amount as cash for a Marketplace plan. It would also give every worker an appointment with a free enrollment helper before their last day. The aim is that nobody goes from a paycheck to no insurance in the same week. What''s new is making this a standard, public pledge with a fixed price tag, rather than something negotiated case by case.', '"layoff health bridge: employers pay three months of coverage and a sign-up helper"', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "business", "who": {"government": "States could give a tax credit to employers that fund the bridge, or require it for layoffs big enough to need advance notice under the federal WARN Act and state versions of it. Unemployment offices could send every new claimant to a Marketplace application and a local assister.", "means": "Large employers can sign the pledge now and build it into severance. Investors and boards can ask for it in any restructuring plan. Benefits brokers and payroll companies can offer it as a standard add-on. Philanthropists and foundations can set up a pooled fund that pays the bridge for workers at small businesses that close or downsize and can''t afford it. That is where the gap is, since COBRA generally applies only to employers with 20 or more workers (Department of Labor).", "you": "If you''re being laid off, ask HR two questions in writing: \"Will the company pay any of my COBRA premiums, or give me the equivalent in cash?\" and \"Can I meet with a benefits or enrollment helper before my last day?\" Then fill out a HealthCare.gov application to compare prices before you choose."}, "sources": 6, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/health-care-costs/solutions/layoff-health-bridge.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = '"layoff health bridge: employers pay three months of coverage and a sign-up helper"');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'jobs-and-layoffs', 'AI transition pay funded by the companies gaining from AI', 'When AI takes over work people used to do, the productivity gain shows up for the company using it, while the income loss shows up for the worker displaced. This idea connects the two: the companies gaining most from AI pay into a transition fund that tops up the wages of displaced workers who take a lower-paying job, and pays for proven training. The top-up idea is not new. The U.S. tested it for trade-displaced workers, and it helped people get back to work faster. What''s new is applying it to AI and having the biggest winners pay for it.', 'ai transition pay funded by the companies gaining from ai', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "federal", "who": {"government": "Congress can create a general displacement wage insurance program (the trade-only version stopped taking new groups of workers in July 2022) and let private contributions fund it. States can pilot it with their own funds.", "means": "The AI labs, cloud providers and large employers that report the biggest AI-driven savings can jointly seed the fund now, without waiting for law, for example by pledging a fixed share of AI-related revenue or of the savings from each automated role. Investors and philanthropists can fund a randomized pilot in one or two states so there''s hard evidence within a few years. Any company that automates roles can offer this top-up to its own laid-off workers on its own.", "you": "If you were laid off and are weighing a lower-paying job, take the job offer seriously rather than waiting: the research shows faster re-employment pays off over time. File for unemployment first, and ask your local American Job Center whether any wage-supplement or training funds apply to your layoff."}, "sources": 7, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/jobs-and-layoffs/solutions/ai-transition-pay.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'ai transition pay funded by the companies gaining from ai');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'jobs-and-layoffs', 'Your first week after a layoff or hours cut', 'The help that already exists after a job loss has deadlines and waiting periods, and people lose money by waiting. This is a short checklist of free programs to claim in the first days: unemployment benefits, health coverage, and the free job and training help at American Job Centers.', 'your first week after a layoff or hours cut', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "States can let people file for unemployment and health coverage in one online step, send a checklist like this with every layoff notice, and cut the wait for the first payment.", "means": "Employers doing layoffs can hand every worker this checklist on the last day, pay for a few months of health premiums, give severance that bridges the two-to-three-week wait for benefits, and invite the state Rapid Response team on site before the last day. Philanthropists and community foundations can fund navigators who help people file.", "you": "Search \"[your state] unemployment insurance apply\" and file today, then check HealthCare.gov for a plan before your coverage ends. Both are free."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/jobs-and-layoffs/solutions/first-week-after-a-layoff.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'your first week after a layoff or hours cut');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'jobs-and-layoffs', 'Free sector-focused job training with a track record', 'Most job training doesn''t move earnings much. One kind does: "sectoral" programs that train people for specific jobs employers are hiring for, screen applicants carefully, and add coaching and help with bills and child care. Randomized trials of Year Up, Project QUEST and Per Scholas found earnings gains that lasted for years. Several are free to the trainee.', 'free sector-focused job training with a track record', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "community", "who": {"government": "States and local workforce boards can steer more of their federal training money (WIOA) toward programs with randomized evidence, and pay for the supports (child care, transport, stipends) that keep people enrolled. Cities can link community colleges to employers in growing sectors.", "means": "Employers can co-design curricula, host paid internships and commit to interview graduates. Companies cutting jobs because of automation can fund cohorts for the people they let go. Philanthropists can pay for expansion to new cities. Amazon, for example, committed over $1.2 billion from 2019 through 2025 to give 300,000 employees access to free training; more employers can do this, and open it to workers they lay off.", "you": "Check whether Year Up (if you''re 18 to 29) or Per Scholas has a campus or track near you and start an application; both are free. Then visit your local American Job Center (find it through your state''s labor department) and ask about Dislocated Worker training funds if you were laid off."}, "sources": 8, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/jobs-and-layoffs/solutions/sectoral-job-training.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'free sector-focused job training with a track record');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'jobs-and-layoffs', '"Work-sharing: cut hours for everyone instead of laying some off"', 'When business slows, an employer can cut everyone''s hours a little instead of laying some people off entirely. Under state "work-sharing" (short-time compensation) programs, workers collect partial unemployment benefits for the hours lost, keep their health and retirement benefits, and keep their jobs. About 30 states run these programs today, but many employers and workers have never heard of them.', '"work-sharing: cut hours for everyone instead of laying some off"', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "business", "who": {"government": "States without a program can pass one using federal model legislation. States with one can make the employer application online and simple, and tell every employer filing a layoff notice that work-sharing exists.", "means": "Employers facing a temporary slowdown can choose work-sharing before layoffs and keep the trained team they will need again. Larger companies can go further and top up pay so workers on reduced hours lose less. Industry associations and chambers of commerce can teach members how to file a plan.", "you": "If your hours are being cut or layoffs are rumored, look up \"shared work\" or \"work share\" on your state labor department''s website, print the page and ask HR or your manager whether the company will file a plan. If you''ve already lost hours, ask your state unemployment agency whether you can claim partial benefits."}, "sources": 3, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/jobs-and-layoffs/solutions/work-sharing-instead-of-layoffs.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = '"work-sharing: cut hours for everyone instead of laying some off"');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'medical-debt', 'Apply for the hospital''s financial assistance (charity care), even after the bill is in collections', 'Every nonprofit hospital in the U.S. must have a written financial assistance policy that gives free or discounted care to patients who meet its income rules, and must cap what eligible patients are charged. Many people who qualify never apply because nobody told them. Applying can erase or cut a hospital bill, stop collection actions, and in some cases get money back and negative credit entries removed.', 'apply for the hospital''s financial assistance (charity care), even after the bill is in collections', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "The IRS enforces section 501(r) as a condition of hospitals'' tax exemption; it could audit more hospitals'' notice and screening practices and publish results. States can set minimum eligibility levels (as Maryland does), extend the rules to for-profit hospitals, and require reporting of how many patients were screened and approved.", "means": "Fund nonprofit application helpers like Dollar For so every hospital region has one. Hospitals can print the eligibility table on the front of every bill and staff a financial counselor at discharge. Employers can add a patient-advocate benefit that files these applications for workers.", "you": "Find your hospital''s policy online. Call billing and say: \"I''d like to apply for financial assistance under your policy. Please put my account on hold while it''s reviewed and send me the application.\" Mail or upload it with proof of income, keep copies, and write down the date and the name of everyone you speak with. If a collector calls, tell them you''ve applied for the hospital''s financial assistance and ask them to send the account back to the hospital for review."}, "sources": 7, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/medical-debt/solutions/apply-for-hospital-financial-assistance.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'apply for the hospital''s financial assistance (charity care), even after the bill is in collections');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'medical-debt', 'Get the itemized bill, dispute what''s wrong, and negotiate the rest before paying', 'Medical bills and collection notices often include charges that can''t legally be collected: services never received, amounts insurance already paid, surprise bills banned by federal law, or debts that should have been covered by financial assistance. Federal rules give people the right to see the details, dispute the debt in writing and negotiate. Doing this before paying anything can shrink or erase the amount owed.', 'get the itemized bill, dispute what''s wrong, and negotiate the rest before paying', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "States can copy Colorado''s itemization-before-collection and appeal-pause rules and its 3% interest cap. Federal and state agencies can require every medical bill and collection letter to state, in plain words, the right to an itemized bill and to financial assistance. State attorneys general can take and publish complaints about medical billing.", "means": "Fund free medical-billing advocates at legal aid offices and community health centers. Employers and unions can offer bill review as a benefit. Hospitals and physician groups can send an itemized bill automatically with every balance over a set amount, and stop interest on patient balances.", "you": "Pick your largest medical bill. Call or write: \"Please send me a fully itemized bill with procedure codes, and put the account on hold until I''ve reviewed it.\" If a collector has it, send the CFPB sample letter asking for proof of the debt and the itemized charges. Pull your insurer''s explanation of benefits for the same date and mark every charge that doesn''t match. Don''t pay or agree to a payment plan by phone until you have the itemized bill."}, "sources": 6, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/medical-debt/solutions/check-dispute-and-negotiate-the-bill.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'get the itemized bill, dispute what''s wrong, and negotiate the rest before paying');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'medical-debt', 'State and local governments buy and cancel residents'' medical debt for pennies on the dollar', 'Old medical debt is bought and sold among collectors for a small fraction of its face value. States, counties and cities now use that market in reverse: they pay the nonprofit Undue Medical Debt to buy residents'' qualifying debt from hospitals and collectors and cancel it. Illinois says it erased more than $1.4 billion for almost 700,000 residents with under $10 million in state funds. Residents don''t apply; they get a letter saying the debt is gone.', 'state and local governments buy and cancel residents'' medical debt for pennies on the dollar', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "state", "who": {"government": "A governor, legislature, county board or city council appropriates funds and signs a contract with a debt-relief nonprofit. To get lasting value, pair relief with rules that stop new debt from forming: automatic charity-care screening, limits on interest, liens and garnishment, and credit-reporting limits (see the other solutions in this folder).", "means": "Philanthropists can fund a buy-and-forgive round for a whole region, as the Atrius Health Equity Foundation did in Massachusetts; at Illinois''s ratio, under $10 million cleared $1.4 billion. Hospitals and health systems can sell or donate their unpaid patient accounts to a relief nonprofit instead of to a debt buyer, or cancel balances for low-income patients directly. Employers and foundations can match public funds so counties without budgets still take part.", "you": "Ask your state legislator, county commissioner or city council member, by email or at a public meeting, whether your area has a medical debt relief program and, if not, to fund one modeled on Illinois. If you''ve had a medical bill go to collections, watch your mail for a relief letter, and check your state treasury or health department site for any program. You don''t need to pay anyone to be included: legitimate programs don''t charge."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/medical-debt/solutions/government-funded-medical-debt-buy-and-forgive.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'state and local governments buy and cancel residents'' medical debt for pennies on the dollar');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'medical-debt', 'Screen every patient for financial assistance automatically, before the first bill goes out', 'Most people who qualify for hospital charity care never get it, because they have to find out it exists and apply while sick or behind on bills. Flip the default: before any patient balance is billed, the provider checks eligibility automatically using information it''s already allowed to use, applies the discount, and the patient gets a bill they can actually pay, or none at all. Debt that never forms doesn''t need to be forgiven later.', 'screen every patient for financial assistance automatically, before the first bill goes out', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "state", "who": {"government": "State legislatures can pass a \"screen before you bill\" law covering all licensed providers, with reporting and a patient right to sue if it''s skipped (the Commonwealth Fund review notes only a handful of states, such as Delaware and New Mexico, give patients that right). State Medicaid and SNAP agencies can offer providers a secure yes/no eligibility check. The IRS could make presumptive screening a standard part of 501(r) compliance reviews.", "means": "Health systems can adopt this voluntarily now; the rules already allow it, and it may cut the cost of chasing bills that later get written off. Foundations can pay for a statewide pilot and an independent evaluation at a few hospitals, comparing debt and collections before and after. Software and billing companies can build the screen into standard billing systems and offer it at low cost to rural and safety-net hospitals.", "you": "If you''re getting care, ask at registration or discharge: \"Can you screen me for financial assistance before you bill me?\" If you already have a bill, apply now (see the hospital financial assistance solution in this folder). Then write or call your state legislators and ask them to require automatic screening before billing."}, "sources": 6, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/medical-debt/solutions/screen-every-patient-before-the-first-bill.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'screen every patient for financial assistance automatically, before the first bill goes out');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'no-financial-cushion', 'Before cashing out a 401(k) for rent, use the cheaper options first', 'When a layoff or a cut in hours hits, cashing out a whole 401(k) can feel like the only way to keep the rent paid. It is usually the most expensive way: 20% is withheld up front, the rest is taxed as income, and a 10% additional tax may apply. Several existing options, from unemployment insurance to a penalty-free $1,000 emergency withdrawal, can cover the gap while keeping most of the retirement money intact.', 'before cashing out a 401(k) for rent, use the cheaper options first', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "The IRS and Department of Labor could require plans to show the $1,000 emergency option and the costs of a full cash-out on every separation notice and withdrawal screen, in plain numbers. States could include a \"before you cash out\" page in every unemployment claim confirmation.", "means": "Employers can switch on the $1,000 emergency distribution and hardship options in their plans, and have HR walk every laid-off worker through this list before their last day. Recordkeepers can put a tax-cost calculator in front of the \"cash out\" button. Philanthropists can fund free financial coaching for people in the first month after a layoff.", "you": "Before you request any withdrawal, call your plan''s phone number and ask three questions: Do you offer the $1,000 emergency personal expense distribution? Do you offer hardship distributions for eviction? What will I actually receive after withholding if I cash out? Then file for unemployment and call 211."}, "sources": 6, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/no-financial-cushion/solutions/before-you-cash-out-a-401k.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'before cashing out a 401(k) for rent, use the cheaper options first');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'no-financial-cushion', 'Employer emergency savings accounts with a seed and a match', 'Employers can give workers a separate, easy-to-reach emergency savings account funded straight from the paycheck, ideally with a starting deposit and a match. Federal law now allows this inside a retirement plan (a "pension-linked emergency savings account", or PLESA), and large employers already run stand-alone versions. Early results show people use the money for emergencies instead of raiding their 401(k).', 'employer emergency savings accounts with a seed and a match', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "business", "who": {"government": "Congress could let employers put matches directly into the PLESA (today matches go to the retirement side) and give small businesses a tax credit for seeding accounts. States could add an emergency savings pocket to any state-run savings program for workers without a workplace plan.", "means": "Every large employer can turn this on. The ambitious version: seed every hourly worker''s account with $500 on day one and match the next $500. Foundations can follow The BlackRock Foundation, which committed $50 million to this work, by paying for seed deposits at small employers that can''t afford them.", "you": "Ask HR or your benefits portal whether your employer offers an emergency savings account or PLESA. If it does, sign up, even at $10 a paycheck. If not, set up a split direct deposit that sends a fixed small amount to a separate savings account you don''t see every day."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/no-financial-cushion/solutions/employer-emergency-savings-accounts.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'employer emergency savings accounts with a seed and a match');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'no-financial-cushion', 'Fast, one-time emergency cash before a crisis turns into an eviction', 'For someone with no savings, one missed paycheck can snowball into late fees, an eviction filing and losing their home. Local emergency financial assistance pays a one-time amount, usually straight to the landlord or utility, at the moment of crisis (the Santa Clara program, for example, pays rent to landlords and other household expenses such as utilities). Two rigorous studies found it sharply reduces homelessness, and the benefits exceed the cost. Before the pandemic, 93% of communities had a help line to call for this kind of help (Phillips and Sullivan, citing 211.org); the funds behind them need to be faster, better known and better funded.', 'fast, one-time emergency cash before a crisis turns into an eviction', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "community", "who": {"government": "Cities, counties and states can fund standing emergency assistance pools that don''t run dry mid-year, pay within days rather than weeks, and let people apply by phone or text with simple paperwork. Courts can refer every tenant at an eviction filing to the fund.", "means": "This is one of the most direct, measurable gifts available. A local donor or company could endow a year-round fund for their own county, for example committing to cover every eligible household that calls, and pay for an independent evaluation like the ones above. Landlords with large portfolios can agree to accept fund payments and pause filings while an application is pending. Employers can add a no-questions emergency grant for their own staff.", "you": "If you''re behind or about to be, dial 211 (or visit 211.org) now, before an eviction notice, and ask specifically for \"emergency rental assistance\" or \"emergency financial assistance\" in your county. Have your lease, the amount owed and proof of income ready."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/no-financial-cushion/solutions/fast-one-time-emergency-cash.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'fast, one-time emergency cash before a crisis turns into an eviction');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'no-financial-cushion', 'A "first $1,000" cushion fund, seeded by people and companies with means', 'Most advice tells people with no savings to start saving. That''s hard when every dollar is spoken for. This idea flips the order: philanthropists and companies put the first $1,000 into a worker''s own emergency account, and the worker keeps it topped up with matched small deposits. The cushion exists on day one, so the next car repair or late paycheck doesn''t become a debt spiral or a 401(k) cash-out.', 'a "first $1,000" cushion fund, seeded by people and companies with means', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "community", "who": {"government": "Cities or states could add public matching money, and Congress could make donor-funded seed deposits tax-free to the recipient and not count them against benefit asset limits, so the cushion doesn''t cost anyone their SNAP or Medicaid. (Those rules vary by program and would need checking.)", "means": "This is the ask. $10 million seeds 10,000 workers. A billionaire, a family foundation or a coalition of a region''s largest employers could fund a whole metro area. The BlackRock Foundation''s $50 million commitment to workplace emergency savings shows the scale is realistic. Employers can enroll their own low-wage staff and add the refill match. Banks and credit unions can hold the accounts with no fees and no minimums.", "you": "Start your own first $100 in a separate account. SaverLife, a philanthropy-funded nonprofit, offers cash rewards for building savings habits and reports that 61% of members reach $500 in savings within six months of joining."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/no-financial-cushion/solutions/first-1000-cushion-fund.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'a "first $1,000" cushion fund, seeded by people and companies with means');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'predatory-finance', 'Give every U.S. bank customer a one-tap gambling block with a 48-hour wait to turn it off', 'Banks in the UK, Ireland and Australia let customers switch on a block that declines card payments to gambling merchants, and some make you wait 48 hours before the block can be lifted. That delay is the point: it gives a person a cooling-off window against a late-night urge to chase losses. We could not find a U.S. bank or credit union that advertises this, even though online sports betting is now linked to more bankruptcies and debt in collections in the states that allow it. The idea: U.S. banks, credit unions and card issuers offer the same block, by default in their apps.', 'give every u.s. bank customer a one-tap gambling block with a 48-hour wait to turn it off', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "idea", "status": "proposed", "scale": "business", "who": {"government": "State gaming regulators could require licensed sportsbooks to keep using correct merchant codes so bank blocks work, and to honor a customer''s bank block instead of steering them to other payment methods. State and federal bank regulators could make clear that offering the block is a consumer-protection feature they welcome.", "means": "Large banks, card networks and credit unions can build this in one product cycle; the payment codes already exist. Fintech founders can offer it to small banks and credit unions as a ready-made card-control module. Philanthropists and researchers can fund a randomized study with a willing bank to measure whether blocks reduce overdrafts, missed payments and gambling losses.", "you": "If betting is draining you or someone you love, call or text the National Problem Gambling Helpline at 1-800-MY-RESET, or use its online chat, to reach help in your state. Then call your bank or credit union and ask whether it can block gambling merchants on your card. If it can''t, ask them to add the feature and consider moving to a bank that will."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/predatory-finance/solutions/bank-gambling-block-with-cooling-off.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'give every u.s. bank customer a one-tap gambling block with a 48-hour wait to turn it off');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'predatory-finance', 'Switch to a Bank On certified account with no overdraft fees, and take back control of auto-debits', 'Bank On certified accounts are low-cost checking accounts from regular banks and credit unions that meet national standards, including **no overdraft or non-sufficient-funds fees** and a monthly fee of $5 or less. Over 14 million were open and active at the end of 2024. For someone losing $35 at a time to overdrafts, switching can stop the drain this week, and pairing it with the federal right to revoke automatic debits puts the person, not the lender, in charge of when money leaves.', 'switch to a bank on certified account with no overdraft fees, and take back control of auto-debits', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "Local Bank On coalitions are partnerships between local public officials, government agencies, financial institutions and community groups. A city or county without one can start one. A city or state could pay benefits, tax refunds and payroll for public employees into certified accounts by default when people don''t name another account. Regulators can keep publishing overdraft data so people can compare.", "means": "Banks and credit unions can certify an account (the list is public) and report results to the St. Louis Fed''s Bank On data hub. Employers can show certified options during onboarding next to the direct deposit form. Philanthropists can fund local Bank On coalitions and the free financial coaching that helps people switch. Fintech founders can build low-balance alerts and \"move this bill date\" tools that work with these accounts.", "you": "Open the list of certified accounts at https://joinbankon.org/accounts/, find your state, and pick a bank or credit union near you. Open the account, move your direct deposit, and then use the CFPB steps to move or revoke automatic debits from your old account, especially loan payments, so one auto-debit can''t wipe out your grocery money again."}, "sources": 8, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/predatory-finance/solutions/bank-on-certified-no-overdraft-account.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'switch to a bank on certified account with no overdraft fees, and take back control of auto-debits');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'predatory-finance', 'Use a credit union payday alternative loan (PAL) instead of a payday loan', 'Federal credit unions are allowed to make small "payday alternative loans" of up to $2,000, capped at 28% annual interest plus an application fee of no more than $20, repaid in installments over up to a year, with no rollovers. A payday loan averages about $375 and costs the typical borrower about $520 in interest a year because people keep re-borrowing. A PAL is a cheaper way to cover the same gap.', 'use a credit union payday alternative loan (pal) instead of a payday loan', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "individual", "who": {"government": "The NCUA already allows PALs. State credit union regulators could adopt the same terms for state-chartered credit unions where they don''t already, and states could fund loan-loss reserves so small credit unions can afford to offer PALs without risking their capital.", "means": "Philanthropists and community foundations can fund loan-loss reserves or deposits at local credit unions, especially community development credit unions, so they can make more PALs. Employers can partner with a credit union so employees can join through work and repay by payroll deduction. Fintech builders can give credit unions cheap, fast underwriting and same-day funding so a PAL is as quick as a payday storefront.", "you": "Use the NCUA''s Credit Union Locator (https://mapping.ncua.gov/) to find federal credit unions near you and check which ones you can join (many accept anyone who lives or works in an area). Call and ask: \"Do you offer payday alternative loans, PAL I or PAL II, and how fast can I get one?\" Join now, even before you need it, so the PAL I one-month wait is behind you."}, "sources": 5, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/predatory-finance/solutions/credit-union-payday-alternative-loans.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'use a credit union payday alternative loan (pal) instead of a payday loan');
INSERT INTO ideas (problem, title, body, title_key, voter_hash, ip_hash, source, approved, created_at, detail) SELECT 'predatory-finance', 'Pass state small-loan rules like Ohio''s 2018 law, with low rate caps and affordable installments', 'Payday and title loans are regulated mostly by states, and federal protections are uncertain: the CFPB''s remaining payday-loan payment rule took effect in March 2025 but the agency said it would not prioritize enforcing it and plans to reconsider it. States can act on their own. Ohio''s 2018 Fairness in Lending Act turned two-week balloon loans into short installment loans with hard caps on total cost, and state officials estimated it would save Ohio consumers $75 million a year.', 'pass state small-loan rules like ohio''s 2018 law, with low rate caps and affordable installments', 'repo', 'repo', 'repo', 1, 1792195200000, '{"type": "existing", "status": "proposed", "scale": "state", "who": {"government": "State legislatures pass the law; state financial regulators license lenders, enforce it and publish the data. Attorneys general can act against unlicensed online lenders. Ohio''s bill was co-sponsored by a Republican and a Democrat, so this does not have to be a partisan fight.", "means": "Banks and credit unions can commit to offering small installment loans within the new caps so credit doesn''t dry up. Responsible lenders and fintechs can show legislators their loss rates at these prices. Foundations can fund the borrower research and data analysis that gave Ohio''s legislators confidence, the way Pew did there.", "you": "Find out what your state allows. Your state''s financial regulator (often called the department of financial institutions or banking) lists licensed lenders and takes complaints. Before signing any payday or title loan, ask for the total dollar cost, not just the fee, and check the lender is licensed in your state. Then tell your state legislator, in two sentences, what a payday or title loan cost you."}, "sources": 4, "url": "https://github.com/DaryllGomas/town-hall/blob/main/problems/predatory-finance/solutions/state-small-loan-reform-ohio-model.md"}' WHERE NOT EXISTS (SELECT 1 FROM ideas WHERE source = 'repo' AND title_key = 'pass state small-loan rules like ohio''s 2018 law, with low rate caps and affordable installments');
